import{_ as s,l as o,o as e,c as n,v as t,p as l,x as r,d as h,i as m,S as p}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"时间层级定理","description":"","frontmatter":{"title":"时间层级定理","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/time-hierarchy.md","filePath":"cs/time-hierarchy.md","lastUpdated":1789023840000}'),d={name:"cs/time-hierarchy.md"};function c(f,a,P,E,_,u){const i=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="时间层级定理" tabindex="-1">时间层级定理 <a class="header-anchor" href="#时间层级定理" aria-label="Permalink to &quot;时间层级定理&quot;">​</a></h1><div class="epigraph"><p>多给一点时间，就能判定严格更多的语言：对角化相对时钟仍然有效，只要函数时间可构造。</p><footer>—— 据 Hartmanis and Stearns, On the Computational Complexity of Algorithms, 1965；Sipser 整理</footer></div><p>上一课<a href="/cs/combinators-fixed-point">组合子与不动点</a>收束可计算性，从未数过步。<a href="/cs/p-vs-np">P 与 NP</a> 在算法课命名了多项式圈子，但没有证明「更多时间真的更多」。缺口是<strong>时间层级</strong>：对时间可构造的 \\(f\\)，\\(g(n)=o(f(n)/\\log f(n))\\)（单带细节以教材为准）时 \\(\\mathrm{DTIME}(g)\\subsetneq\\mathrm{DTIME}(f)\\)。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>可计算性里对角化不看步数。加上时钟：通用机模拟 \\(M\\) 至多 \\(f(|x|)\\) 步，超时则拒绝，并翻转 \\(M\\) 对自己编码的答案。只要模拟开销小于 \\(f\\) 相对 \\(g\\) 的空隙，新语言在 \\(\\mathrm{DTIME}(f)\\) 不在 \\(\\mathrm{DTIME}(g)\\)。时间可构造：\\(f(|x|)\\) 可在 \\(O(f)\\) 步内在带上写下 \\(f\\) 个记号，否则时钟本身作弊。</p><p>于是 \\(P\\subsetneq\\mathrm{EXP}\\) 等严格包含有着落。\\(P\\) 对 \\(\\mathrm{NP}\\) 的包含是否真，层级管不到——那是同一量级内部。</p><h3 id="不是「指数一定更强」的口号" tabindex="-1">不是「指数一定更强」的口号 <a class="header-anchor" href="#不是「指数一定更强」的口号" aria-label="Permalink to &quot;不是「指数一定更强」的口号&quot;">​</a></h3><p>必须固定模型（多带 vs 单带，对数因子不同）。必须 \\(f\\) 可构造：不可构造的怪函数可以塌缩。层级给的是无穷多层，不是 \\(P\\) vs \\(NP\\)。</p><p><span class="marginnote">Hartmanis–Stearns 1965 开创复杂度。Sipser 第 9 章写确定性时间层级。空间层级更干净（无 \\(\\log\\) 因子），下一课空间。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>陈述：多带 TM 上 \\(\\mathrm{DTIME}(n^k)\\subsetneq\\mathrm{DTIME}(n^{k+1})\\) 一类。证明想法：模拟 + 翻转 + 超时。不要具体算通用机的每一步常数。对照：停机问题不可判定，层级语言都可判定，只是慢。</p>',11)),(e(),l(p,null,{default:r(()=>[m(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20CLK%5B%22%E6%97%B6%E9%97%B4%E5%8F%AF%E6%9E%84%E9%80%A0%20f%22%5D%20--%3E%20SIM%5B%22%E6%A8%A1%E6%8B%9F%E8%87%B3%E5%A4%9A%20f%20%E6%AD%A5%22%5D%0A%20%20SIM%20--%3E%20FLIP%5B%22%E5%AF%B9%E8%A7%92%E7%BF%BB%E8%BD%AC%22%5D%0A%20%20FLIP%20--%3E%20SEP%5B%22DTIME(g)%20%E2%89%A0%20DTIME(f)%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>主干渐近记号已有；这里 \\(O\\) 的对象是 TM 步数，输入长度 \\(|x|\\)。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>有了严格层级，才能说「指数时间里有可判定但假定不在 P 的语言」而不只是停机。NPC 完全问题若在 P 则整层塌到 P，与层级不矛盾：层级比较的是不同阶的函数，不是 NP 内部。</p><p>非确定时间层级也存在（更精细），本课不写。</p><p>空间层级几乎没有 \\(\\log\\) 因子，因为可以精确数格子；时间模拟要扫带，空隙必须更宽。间隙定理表明：若 \\(f\\) 不可构造，可能 \\(\\mathrm{DTIME}(f)=\\mathrm{DTIME}(2^f)\\)。课堂函数 \\(n^k,2^n\\) 都可构造。\\(P\\subsetneq\\mathrm{EXP}\\) 是本课最常用的推论，仍不碰到 \\(NP\\)。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证间隙定理（怪 \\(f\\) 使 \\(\\mathrm{DTIME}(f)=\\mathrm{DTIME}(2^f)\\) 一类），不引入相对论化。后课默认：更多（可构造）时间 \\(\\Rightarrow\\) 严格更多语言。下一课空间：PSPACE 与 Savitch。</p><p>层级比较的是不同阶的可构造函数，不是 NP 内部。因此 \\(P\\subsetneq\\mathrm{EXP}\\) 与 \\(P\\stackrel{?}{=}NP\\) 可以同时成立。后课空间层级更干净，Savitch 再把非确定空间平方掉。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>时间可构造前提下，确定性时间类严格递增。</li><li>手段仍是对角化，加上时钟。</li><li>不解决 \\(P\\) 对 \\(NP\\)；只分开不同阶。</li><li>出处：Hartmanis and Stearns, 1965；Sipser。</li></ul>',10))])}const D=s(d,[["render",c]]);export{A as __pageData,D as default};
